from __future__ import annotations

import ast
import base64
import gzip
import hashlib
import os
import py_compile
from pathlib import Path

ROOT = Path.cwd()
FILES = {
    "models": ROOT / "wa_backend" / "models.py",
    "schemas": ROOT / "wa_backend" / "schemas.py",
    "services": ROOT / "wa_backend" / "services.py",
    "warehouse": ROOT / "wa_backend" / "api" / "warehouse.py",
}

EXPECTED_SOURCE_SHA256 = {'models': 'a540bc58cd08395569aa8bf0c98039ffd463572bef0dcf4354285a1a4ec71954', 'schemas': 'b1fd7bc60102b12062e9edb3f15b0c67cfac0f81d516d533ffe02dd2cad9ace1', 'services': '537f8694fabb6e0c6ba96deae65eb22e2f03e0795c5371d6aaec63fbb99b8850', 'warehouse': '6d8c34c2cef2c7b5862633c94bc3d89f4ac570c6fb05b3e988988d8b0e632b5e'}
EXPECTED_TARGET_SHA256 = {'models': 'edc98cd8b62be880dd6bb8201c749168dbfedb9aaca8debafb30d8b2f6caf58c', 'schemas': '2aa29d3e2ecb9a9e8e6820eb436a5526130468e0582c49ad5b93f6325cd41e90', 'warehouse': '6c74774173c1e0dab7d417d96108cbc2d3991a01afa5ceeed872ee39d069f1c2'}

COMPRESSED_TARGETS = {
    "models": '',
    "schemas": '',
    "warehouse": '',
}


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def main() -> None:
    # Fail closed: this patch is valid ONLY for the four exact snapshots audited.
    originals = {}
    for name, path in FILES.items():
        if not path.is_file():
            raise SystemExit(f"ERROR: missing {path}")
        raw = path.read_bytes()
        originals[name] = raw
        actual = sha256(raw)
        expected = EXPECTED_SOURCE_SHA256[name]
        if actual != expected:
            raise SystemExit(
                f"REFUSED: {path} is not the audited snapshot. "
                f"expected={expected}, actual={actual}. "
                "Do not force this patch; upload the current file instead."
            )

    prepared = {}
    for name, encoded in COMPRESSED_TARGETS.items():
        raw = gzip.decompress(base64.b64decode(encoded))
        if sha256(raw) != EXPECTED_TARGET_SHA256[name]:
            raise RuntimeError(f"Embedded target integrity failure: {name}")
        text = raw.decode("utf-8")
        ast.parse(text, filename=str(FILES[name]))
        prepared[name] = raw

    # Architectural invariants checked before writing anything.
    model_text = prepared["models"].decode("utf-8")
    schema_text = prepared["schemas"].decode("utf-8")
    warehouse_text = prepared["warehouse"].decode("utf-8")

    required = {
        "models": (
            "ix_transfer_header_transit_queue",
            "chk_transfer_header_session_scope",
            "chk_transfer_header_received_by_scope",
            "chk_transfer_header_separation_of_duties",
        ),
        "schemas": (
            "class UnifiedTransferDecisionRequest",
            "class WarehouseTransferCursorPage",
            "class WarehouseTransferDetail",
            "class UnifiedReceiveRequest(RequestModel):\n    request_id: UUID",
        ),
        "warehouse": (
            'operation="WAREHOUSE_TRANSFER_RECEIVE"',
            'operation="WAREHOUSE_TRANSFER_CANCEL"',
            'operation="WAREHOUSE_TRANSFER_REJECT"',
            '"/warehouse/unified/transfers"',
            '"/warehouse/unified/transfers/{header_id}"',
            "expected_scope=scope",
        ),
    }
    target_texts = {
        "models": model_text,
        "schemas": schema_text,
        "warehouse": warehouse_text,
    }
    for name, tokens in required.items():
        for token in tokens:
            if token not in target_texts[name]:
                raise RuntimeError(f"Target invariant missing in {name}: {token}")

    if 'decision_reason: str = Body(..., embed=True)' in warehouse_text:
        raise RuntimeError("Legacy non-idempotent transfer decision body remains.")

    # Compile temporary targets before atomic replacement.
    temp_paths = {}
    try:
        for name, raw in prepared.items():
            path = FILES[name]
            tmp = path.with_name(path.name + ".interwarehouse.tmp")
            tmp.write_bytes(raw)
            py_compile.compile(str(tmp), doraise=True)
            temp_paths[name] = tmp

        replaced = []
        try:
            for name in ("models", "schemas", "warehouse"):
                os.replace(temp_paths[name], FILES[name])
                replaced.append(name)
        except Exception:
            for name in replaced:
                FILES[name].write_bytes(originals[name])
            raise

        # Verify bytes after replacement; services.py must remain untouched.
        for name in ("models", "schemas", "warehouse"):
            actual = sha256(FILES[name].read_bytes())
            if actual != EXPECTED_TARGET_SHA256[name]:
                raise RuntimeError(
                    f"Post-write hash mismatch for {FILES[name]}: {actual}"
                )

        if sha256(FILES["services"].read_bytes()) != EXPECTED_SOURCE_SHA256["services"]:
            raise RuntimeError("services.py changed unexpectedly.")

    except Exception:
        for tmp in temp_paths.values():
            if tmp.exists():
                tmp.unlink()
        # Restore all modified targets on any validation/write failure.
        for name in ("models", "schemas", "warehouse"):
            if FILES[name].exists() and sha256(FILES[name].read_bytes()) != EXPECTED_SOURCE_SHA256[name]:
                FILES[name].write_bytes(originals[name])
        raise

    print("WAREHOUSE_INTERWAREHOUSE_HARDENING_PATCH_OK")
    print("PY_COMPILE=OK")
    print("TRANSFER_TERMINAL_IDEMPOTENCY=ENABLED")
    print("TRANSFER_LIST_AND_DETAIL_API=ENABLED")
    print("TRANSFER_CURSOR_SCOPE=TENANT_AND_FILTER_BOUND")
    print("TRANSFER_DB_AUDIT_CONSTRAINTS=HARDENED")
    print("TRANSFER_QUEUE_INDEX=ADDED")
    print("SERVICES_ENGINE=UNCHANGED")
    print("PARTIAL_RECEIPT_POLICY=UNCHANGED_BY_DESIGN")
    print("NEXT=REBUILD_DEV_SCHEMA_AND_RUN_POSTGRES_E2E")


if __name__ == "__main__":
    main()
